:root{
  --ink:#0a0f24;
  --ink-2:#111a38;
  --panel:rgba(10,16,38,.72);
  --panel-line:rgba(174,228,255,.24);
  --cyan:#7df9ff;
  --cyan-deep:#2bc8dc;
  --pink:#ff9ad5;
  --gold:#ffd37a;
  --gold-deep:#d99b3d;
  --rose:#ff6f91;
  --mint:#9dffcf;
  --text:#eef7ff;
  --muted:#a9bdd8;
  --shadow:0 18px 50px rgba(0,4,20,.55);
  --display:Georgia,"Palatino Linotype","Book Antiqua",serif;
  --sans:"Trebuchet MS","Segoe UI",system-ui,sans-serif;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;background:#070b18;color:var(--text);font-family:var(--sans);overflow:hidden;-webkit-tap-highlight-color:transparent}
body{user-select:none}
canvas#game-canvas{position:fixed;inset:0;width:100%;height:100%;display:block;touch-action:none;outline:none}
.hidden{display:none !important}
button{font-family:inherit;color:inherit;border:0;background:none;cursor:pointer}
b{font-weight:700}

/* ---------- shared chrome ---------- */
.eyebrow{display:flex;align-items:center;gap:14px;font-size:11px;letter-spacing:.38em;color:var(--cyan);text-transform:uppercase;font-weight:700;text-shadow:0 0 16px rgba(125,249,255,.6)}
.eyebrow span{height:1px;width:44px;background:linear-gradient(90deg,transparent,var(--cyan));display:inline-block}
.eyebrow span:last-child{background:linear-gradient(90deg,var(--cyan),transparent)}
.btn{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:12px;padding:14px 32px;border-radius:3px;font-size:14px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;transition:transform .18s ease,box-shadow .18s ease,background .18s ease;clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px)}
.btn:hover{transform:translateY(-2px)}
.btn:active{transform:translateY(0) scale(.99)}
.btn-primary{background:linear-gradient(120deg,#7df9ff,#b8f6ff 45%,#ffd9f2);color:#06142a;box-shadow:0 0 0 1px rgba(255,255,255,.6) inset,0 12px 34px rgba(70,224,255,.28)}
.btn-primary:hover{box-shadow:0 0 0 1px rgba(255,255,255,.8) inset,0 16px 44px rgba(70,224,255,.48)}
.btn-primary span{font-size:11px;opacity:.7}
.btn-ghost{background:rgba(12,22,48,.58);border:1px solid rgba(174,228,255,.28);color:#d8ecff;backdrop-filter:blur(8px);clip-path:none;border-radius:2px;box-shadow:0 0 0 1px rgba(0,0,0,.1) inset}
.btn-ghost:hover{border-color:rgba(125,249,255,.7);background:rgba(22,40,78,.72)}
.hidden{display:none!important}

/* ---------- loading ---------- */
#loading{position:fixed;inset:0;z-index:100;background:radial-gradient(ellipse at 50% 40%,#15244a 0%,#080d1d 60%,#04060e 100%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;transition:opacity .7s ease}
#loading.gone{opacity:0;pointer-events:none}
.loading-mark{font-size:34px;color:var(--cyan);animation:spin 3.4s linear infinite;text-shadow:0 0 26px var(--cyan)}
.loading-title{font-family:var(--display);font-size:44px;letter-spacing:.36em;margin-left:.36em}
.loading-bar{width:190px;height:2px;background:rgba(255,255,255,.12);overflow:hidden;margin-top:6px}
.loading-bar i{display:block;height:100%;width:40%;background:linear-gradient(90deg,transparent,var(--cyan),transparent);animation:load 1.2s ease-in-out infinite}
.loading-sub{font-size:10px;letter-spacing:.28em;text-transform:uppercase;color:var(--muted)}
@keyframes load{0%{transform:translateX(-120%)}100%{transform:translateX(360%)}}
@keyframes spin{to{transform:rotate(360deg)}}

/* ---------- title ---------- */
#title-screen{position:fixed;inset:0;z-index:40;display:flex;align-items:center;justify-content:center;transition:opacity .8s ease,visibility .8s}
#title-screen.gone{opacity:0;visibility:hidden;pointer-events:none}
.title-vignette{position:absolute;inset:0;background:
  radial-gradient(ellipse at 50% 58%,rgba(5,9,22,.05) 0%,rgba(5,9,22,.36) 54%,rgba(4,7,17,.86) 100%),
  linear-gradient(180deg,rgba(5,9,22,.46),transparent 30%,transparent 66%,rgba(4,7,17,.8))}
.title-content{position:relative;z-index:2;text-align:center;display:flex;flex-direction:column;align-items:center;animation:rise .9s cubic-bezier(.2,.8,.2,1) both}
@keyframes rise{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:translateY(0)}}
.logo{font-family:var(--display);font-size:clamp(76px,13vw,168px);line-height:.86;margin:16px 0 0;letter-spacing:.12em;margin-left:.12em;font-weight:400;background:linear-gradient(180deg,#fff 12%,#d8fbff 44%,#7df9ff 78%,#3cc3e2 100%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 28px rgba(125,249,255,.35)) drop-shadow(0 18px 34px rgba(0,6,20,.7));position:relative}
.logo-spark{position:absolute;font-size:.14em;top:.12em;right:-.16em;color:#fff;background:none;-webkit-text-fill-color:#fff;filter:drop-shadow(0 0 16px var(--cyan));animation:spark 3s ease-in-out infinite}
@keyframes spark{0%,100%{opacity:.55;transform:scale(.9) rotate(0)}50%{opacity:1;transform:scale(1.2) rotate(45deg)}}
.logo-sub{font-family:var(--display);font-size:clamp(14px,2vw,25px);letter-spacing:.64em;margin:6px 0 0 .64em;color:#f3d9b4;font-weight:400;text-shadow:0 0 20px rgba(255,211,122,.36)}
.title-copy{font-family:var(--display);font-style:italic;font-size:clamp(13px,1.3vw,17px);line-height:1.75;color:#c7d9ee;margin:24px 0 28px;text-shadow:0 2px 12px rgba(0,0,0,.7)}
.title-actions{display:flex;gap:14px;align-items:center}
.title-actions .btn-primary{min-width:190px}
.title-chips{display:flex;gap:22px;margin-top:30px;font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#a9c6de;flex-wrap:wrap;justify-content:center}
.title-foot{margin-top:16px;font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:#7e93ad}
.title-side{position:absolute;right:5vw;bottom:8vh;display:flex;align-items:center;gap:16px;z-index:2;opacity:.75}
.side-line{width:70px;height:1px;background:linear-gradient(90deg,transparent,#ffd37a)}
.side-text{font-size:9px;letter-spacing:.28em;color:#d8c7a6;line-height:1.9;text-align:right}
.side-text b{color:#fff;font-weight:600}

/* ---------- HUD ---------- */
#hud{position:fixed;inset:0;z-index:20;pointer-events:none;padding:22px 26px;font-size:13px}
.hud-top-left{display:flex;gap:12px;align-items:flex-start;filter:drop-shadow(0 8px 24px rgba(0,0,0,.4))}
.portrait{width:64px;height:64px;position:relative;border-radius:2px;background:linear-gradient(145deg,#243c68,#0d1631);border:1px solid rgba(174,228,255,.4);clip-path:polygon(0 0,100% 0,100% 78%,78% 100%,0 100%);overflow:visible}
.portrait-art{position:absolute;inset:2px;display:flex;align-items:center;justify-content:center;font-family:var(--display);font-size:36px;color:#dffcff;background:radial-gradient(circle at 50% 30%,rgba(125,249,255,.35),transparent 62%),linear-gradient(160deg,#2b4a7e,#121a35);text-shadow:0 0 18px var(--cyan)}
.level-badge{position:absolute;right:-7px;bottom:-7px;min-width:24px;height:24px;border-radius:50%;background:linear-gradient(145deg,#ffe7a9,#d99b3d);color:#231503;font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:center;border:1px solid #fff2c9;box-shadow:0 0 14px rgba(255,211,122,.6)}
.stat-stack{display:flex;flex-direction:column;gap:5px;width:min(310px,30vw)}
.name-row{display:flex;align-items:baseline;gap:10px;margin-bottom:1px}
.hero-name{font-family:var(--display);font-size:17px;letter-spacing:.22em;text-shadow:0 0 14px rgba(125,249,255,.4)}
.hero-title{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:#ffd37a;opacity:.9}
.bar{position:relative;height:13px;background:rgba(5,9,22,.72);border:1px solid rgba(174,228,255,.25);overflow:hidden;clip-path:polygon(5px 0,100% 0,100% calc(100% - 5px),calc(100% - 5px) 100%,0 100%,0 5px)}
.bar-fill{position:absolute;inset:0;width:100%;transform-origin:left;transition:width .28s cubic-bezier(.2,.8,.2,1)}
.bar.hp{height:17px}
.bar.hp .bar-fill{background:linear-gradient(90deg,#ff4d6d,#ff8fa8 60%,#ffc0cf);box-shadow:0 0 14px rgba(255,90,120,.55)}
