.minimap-wrap{position:relative;width:158px;height:158px;border-radius:50%;overflow:hidden;border:1px solid rgba(174,228,255,.38);box-shadow:0 0 0 4px rgba(8,14,32,.55),0 10px 30px rgba(0,0,0,.4),0 0 26px rgba(70,224,255,.15);background:rgba(8,16,34,.55)}
