      p.set(x, h + sc * 0.2, z); q.setFromEuler(new THREE.Euler(R(), R() * TAU, R() * 0.4));
      s.set(sc, sc * (0.6 + R() * 0.5), sc); m.compose(p, q, s); rockInst.setMatrixAt(i++, m);
      if (sc > 1.0) colliders.push({ x, z, r: sc * 0.8, type: 'rock' });
