      }
      // crystals
      for (const c of crystals) {
        if (c.collected) continue;
        c.group.position.y = c.pos.y + 1.15 + Math.sin(t * 1.7 + c.phase) * 0.18;
        c.mesh.rotation.y += dt * 1.4;
        c.ring.rotation.z += dt * 0.7;
        const s = 0.9 + Math.sin(t * 2.4 + c.phase) * 0.12;
