function makeHealthBar(width = 1.15) {
  const canvas = document.createElement('canvas');
  canvas.width = 128; canvas.height = 24;
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: true });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(width, width * 0.1875, 1);
  sprite.renderOrder = 8;
  return { sprite, canvas, ctx: canvas.getContext('2d'), tex, width };
}
function drawHealthBar(bar, ratio, boss = false) {
  const { ctx, canvas, tex } = bar;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'rgba(4,6,14,.85)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = boss ? 'rgba(190,120,255,.9)' : 'rgba(220,240,255,.65)';
  ctx.lineWidth = 2; ctx.strokeRect(1, 1, canvas.width - 2, canvas.height - 2);
  const g = ctx.createLinearGradient(0, 0, canvas.width, 0);
  if (boss) { g.addColorStop(0, '#7c2bc4'); g.addColorStop(1, '#e2a5ff'); }
  else { g.addColorStop(0, '#ff4668'); g.addColorStop(0.7, '#ff8a9e'); g.addColorStop(1, '#ffc0c9'); }
  ctx.fillStyle = g;
  ctx.fillRect(4, 4, (canvas.width - 8) * clamp(ratio, 0, 1), canvas.height - 8);
  ctx.fillStyle = 'rgba(255,255,255,.4)';
  ctx.fillRect(4, 4, (canvas.width - 8) * clamp(ratio, 0, 1), 3);
  tex.needsUpdate = true;
}

/* ------------------------------------------------------------------ */
/* enemy manager                                                       */
/* ------------------------------------------------------------------ */
export class EnemyManager {
  constructor(scene, world, vfx, audio, callbacks = {}) {
    this.scene = scene;
    this.world = world;
    this.vfx = vfx;
    this.audio = audio;
    this.callbacks = callbacks;
    this.enemies = [];
    this.boss = null;
    this.bossActive = false;
    this.bossDefeated = false;
    this.spawnTimer = 0;
    this.spawns = [];
    this.dungeonSpawns = [];
    this.resetTimer = 0;
    this._createSpawns();
    this._spawnInitial();
  }

  _createSpawns() {
    const H = (x, z) => this.world.heightAt(x, z);
    const moss = [
      [-25, -5], [-34, -19], [-19, -29], [18, 10], [31, -15], [25, -40],
      [44, 6], [10, -27], [-8, -47], [34, 34], [-45, 22], [58, -18],
    ];
    const shade = [
      [-46, -16], [48, -31], [24, -52], [-20, -46], [60, 8], [36, 30], [-33, 30],
    ];
    for (const [x, z] of moss) this.spawns.push({ type: 'moss', x, z, y: H(x, z), timer: 0, alive: false });
    for (const [x, z] of shade) this.spawns.push({ type: 'shade', x, z, y: H(x, z), timer: 0, alive: false });
  }

  _spawnInitial() {
    for (const s of this.spawns) this.spawnFromSpawn(s);
  }

  spawnFromSpawn(spawn) {
    const e = spawn.type === 'moss' ? this._createMoss(spawn) : this._createShade(spawn);
    spawn.alive = true;
    spawn.enemy = e;
    this.enemies.push(e);
    return e;
  }

  _base(type, spawn, model, stats) {
    model.group.position.set(spawn.x, spawn.y, spawn.z);
    model.group.rotation.y = Math.random() * Math.PI * 2;
    this.scene.add(model.group);
    const bar = makeHealthBar(type === 'boss' ? 4 : 1.15);
    bar.sprite.position.y = model.height + 0.35;
    model.group.add(bar.sprite);
    drawHealthBar(bar, 1, type === 'boss');
    bar.sprite.visible = false;
    const e = {
      type, spawn, group: model.group, model, bar,
      hp: stats.hp, maxHp: stats.hp, speed: stats.speed, damage: stats.damage,
      aggro: stats.aggro, attackRange: stats.attackRange, attackCooldown: stats.attackCooldown,
      xp: stats.xp, coins: stats.coins,
      state: 'idle', stateTime: 0, cooldown: Math.random() * 1.5,
      stun: 0, invuln: 0, flash: 0, dead: false, deathTime: 0,
      kb: new THREE.Vector3(), wander: new THREE.Vector3(), wanderTimer: Math.random() * 2,
      home: new THREE.Vector3(spawn.x, spawn.y, spawn.z),
      engaged: false, hurtTimer: 0, phase: 1, inDungeon: false,
      radius: model.radius, height: model.height, name: stats.name,
    };
    e.wander.copy(e.home);
    return e;
  }

  _createMoss(spawn) {
    const model = makeMossling();
    const e = this._base('moss', spawn, model, { hp: 58, speed: 3.4, damage: 9, aggro: 14, attackRange: 1.7, attackCooldown: 1.5, xp: 28, coins: 8, name: 'Mossling' });
    return e;
  }

  _createShade(spawn) {
    const model = makeShade();
    const e = this._base('shade', spawn, model, { hp: 42, speed: 6.2, damage: 7, aggro: 18, attackRange: 2.0, attackCooldown: 1.0, xp: 40, coins: 13, name: 'Shade Fang' });
    return e;
  }

  spawnBoss() {
    if (this.boss) return this.boss;
    const spawn = { type: 'boss', x: 0, y: 0.3, z: -232 };
    const model = makeBoss();
    const e = this._base('boss', spawn, model, { hp: 620, speed: 3.0, damage: 20, aggro: 30, attackRange: 4.0, attackCooldown: 2.2, xp: 700, coins: 500, name: 'The Hollow King' });
    e.inDungeon = true;
    e.home.set(0, 0.3, -232);
    e.wander.copy(e.home);
    e.bar.sprite.visible = false;
    e.model.group.scale.setScalar(1.05);
    this.boss = e;
    this.enemies.push(e);
    return e;
  }

  startBoss() {
    if (this.bossActive || this.bossDefeated) return;
    const boss = this.spawnBoss();
    this.bossActive = true;
    boss.engaged = true;
    boss.state = 'roar'; boss.stateTime = 0;
    this.callbacks.onBossStart?.(boss);
    this.audio?.bossRoar();
    this.vfx?.shockwave(boss.group.position, 6, 0x9b5cff, 1.0);
  }

  enemyZone(e) {
    return e.inDungeon ? 'dungeon' : 'island';
  }

  get zone() { return this.callbacks.getZone?.() ?? 'island'; }

  _damagePlayer(e) {
    const dmg = e.damage + (e.type === 'boss' && e.phase === 2 ? 5 : 0);
    this.callbacks.onPlayerHit?.(dmg, e.group.position, e);
    if (e.type === 'boss') this.vfx?.shockwave(e.group.position, 5.2, 0x9b5cff, 0.8);
    else this.vfx?.hitSpark(new THREE.Vector3(e.group.position.x, e.group.position.y + 0.8, e.group.position.z), 0xff5577, 10);
  }

  update(dt, playerPos, playerInvuln = false) {
    // respawns
    this.spawnTimer += dt;
    for (const s of this.spawns) {
      if (s.alive) continue;
      s.timer -= dt;
      if (s.timer <= 0 && this.zone === 'island') {
        const d = Math.hypot(playerPos.x - s.x, playerPos.z - s.z);
        if (d > 18) this.spawnFromSpawn(s);
        else s.timer = 3;
      }
    }

    for (const e of [...this.enemies]) {
      if (e.dead) {
        e.deathTime += dt;
        const t = Math.min(1, e.deathTime / 1.1);
        e.group.rotation.z = t * 1.2;
        e.group.position.y = e.spawn.y - t * 0.8;
        e.group.scale.setScalar(1 - t * 0.55);
        e.bar.sprite.visible = false;
        if (e.deathTime > 1.25) {
          this.scene.remove(e.group);
          const i = this.enemies.indexOf(e); if (i >= 0) this.enemies.splice(i, 1);
          if (e.spawn) e.spawn.alive = false;
        }
        continue;
      }
      if (e.inDungeon && this.zone !== 'dungeon') continue;
      if (!e.inDungeon && this.zone !== 'island') continue;

      this._updateEnemy(e, dt, playerPos, playerInvuln);
    }

    // simple separation
    const list = this.enemies.filter(e => !e.dead);
    for (let i = 0; i < list.length; i++) {
      for (let j = i + 1; j < list.length; j++) {
        const a = list[i], b = list[j];
        const dx = b.group.position.x - a.group.position.x;
        const dz = b.group.position.z - a.group.position.z;
        const d = Math.hypot(dx, dz);
        const min = (a.radius + b.radius) * 0.75;
        if (d > 0.001 && d < min) {
          const push = (min - d) * 0.5;
          a.group.position.x -= dx / d * push; a.group.position.z -= dz / d * push;
          b.group.position.x += dx / d * push; b.group.position.z += dz / d * push;
        }
      }
    }
  }

  _updateEnemy(e, dt, playerPos, playerInvuln) {
    const p = e.group.position;
    const dx = playerPos.x - p.x;
    const dz = playerPos.z - p.z;
    const dist = Math.hypot(dx, dz);
    const toPlayer = Math.atan2(dx, dz);
    e.stateTime += dt;
    e.cooldown = Math.max(0, e.cooldown - dt);
    e.stun = Math.max(0, e.stun - dt);
    e.flash = Math.max(0, e.flash - dt);
    if (e.flash <= 0 && e._flashed) this._setFlash(e, false);

    // knockback
    if (e.kb.lengthSq() > 0.0001) {
      p.x += e.kb.x * dt; p.z += e.kb.z * dt;
      e.kb.multiplyScalar(Math.max(0, 1 - dt * 8));
      this._collide(e);
    }

    // face / animate
    const m = e.model;
    if (e.type === 'moss') {
      const t = performance.now() * 0.003 + e.home.x;
      m.body.position.y = Math.abs(Math.sin(t * 2)) * 0.12;
      m.body.rotation.z = Math.sin(t) * 0.04;
    } else if (e.type === 'shade') {
      const t = performance.now() * 0.003 + e.home.z;
      m.body.position.y = 0.72 + Math.sin(t * 1.6) * 0.12;
      m.body.rotation.y += dt * 0.3;
      m.aura.material.opacity = 0.22 + Math.sin(t * 2.4) * 0.08;
    } else if (e.type === 'boss') {
      const t = performance.now() * 0.001;
      m.core.rotation.y += dt * 1.1;
      m.aura.rotation.z += dt * 0.35;
      m.aura.material.opacity = e.phase === 2 ? 0.4 + Math.sin(t * 3) * 0.15 : 0.26 + Math.sin(t * 2) * 0.08;
      m.coreLight.intensity = (e.phase === 2 ? 24 : 12) + Math.sin(t * 4) * 3;
      if (e.state === 'idle' || e.state === 'chase') {
        m.model.position.y = Math.sin(t * 2.2) * 0.06;
        m.arms[0].arm.rotation.x = Math.sin(t * 1.5) * 0.06;
        m.arms[1].arm.rotation.x = -0.2 + Math.sin(t * 1.5) * 0.06;
        m.legs[0].rotation.x = 0; m.legs[1].rotation.x = 0;
      }
    }

    if (e.stun > 0) {
      if (e.type === 'boss') m.model.rotation.x = Math.sin(e.stun * 25) * 0.03;
      return;
    }

    if (e.type === 'boss' && !e.engaged) {
      // idle until player crosses threshold
      if (this.zone === 'dungeon' && playerPos.z < -213) this.startBoss();
      return;
    }

    // state machine
    if (e.state === 'idle') {
      e.wanderTimer -= dt;
      if (e.wanderTimer <= 0) {
        e.wanderTimer = 2 + Math.random() * 3;
        const a = Math.random() * Math.PI * 2;
        e.wander.set(e.home.x + Math.cos(a) * 3, e.home.y, e.home.z + Math.sin(a) * 3);
      }
      const wx = e.wander.x - p.x, wz = e.wander.z - p.z;
      const wd = Math.hypot(wx, wz);
      if (wd > 0.4) {
        p.x += wx / wd * e.speed * 0.28 * dt;
        p.z += wz / wd * e.speed * 0.28 * dt;
        e.group.rotation.y = Math.atan2(wx, wz);
      }
      if (e.type === 'moss') m.body.rotation.y = Math.sin(performance.now() * 0.002 + e.home.x) * 0.2;
      if (dist < e.aggro && !playerInvuln) {
        e.state = 'chase'; e.stateTime = 0; e.engaged = true;
        e.bar.sprite.visible = true;
        if (e.type === 'boss') this.callbacks.onBossEngage?.(e);
      }
    } else if (e.state === 'chase') {
      e.group.rotation.y = toPlayer;
      const speed = e.speed * (e.type === 'boss' && e.phase === 2 ? 1.35 : 1);
      if (dist > e.attackRange * 0.85) {
        p.x += Math.sin(toPlayer) * speed * dt;
        p.z += Math.cos(toPlayer) * speed * dt;
        this._collide(e);
        if (e.type === 'boss') {
          m.legs[0].rotation.x = Math.sin(performance.now() * 0.006) * 0.28;
          m.legs[1].rotation.x = -Math.sin(performance.now() * 0.006) * 0.28;
          m.model.position.y = Math.abs(Math.sin(performance.now() * 0.006)) * 0.1;
        } else if (e.type === 'shade') {
          m.body.rotation.z = Math.sin(performance.now() * 0.006) * 0.12;
        }
      }
      if (e.cooldown <= 0 && dist < e.attackRange) {
        e.state = 'windup'; e.stateTime = 0;
        e.attackKind = e.type === 'boss' ? (dist < 4.5 ? 'slam' : 'cleave') : 'melee';
        this.vfx?.telegraph(new THREE.Vector3(p.x, p.y + 0.05, p.z), e.type === 'boss' ? 5.0 : e.attackRange + 0.6, e.type === 'boss' ? 0xff3c8a : 0xff5c72, e.type === 'boss' ? 0.85 : 0.42);
        if (e.type === 'boss') {
          this.audio?.bossGrowl();
          m.arms[1].arm.rotation.x = -2.6;
        } else {
          this.audio?.enemyWindup();
        }
      }
    } else if (e.state === 'windup') {
      e.group.rotation.y = toPlayer;
      const windDur = e.type === 'boss' ? 0.85 : 0.42;
      const t = e.stateTime / windDur;
      if (e.type === 'boss') {
        m.arms[1].arm.rotation.x = -2.6 + t * 1.2;
        m.model.rotation.x = -0.1 * Math.sin(t * Math.PI);
      } else if (e.type === 'moss') {
        m.body.scale.y = 1 + Math.sin(t * Math.PI) * 0.25;
      } else {
        m.body.position.y = 0.65 + t * 0.3;
      }
      if (e.stateTime >= windDur) {
        // strike
        if (dist < e.attackRange + (e.type === 'boss' ? 2.0 : 1.1)) {
          this._damagePlayer(e);
        }
        if (e.type === 'boss') {
          this.vfx?.shockwave(new THREE.Vector3(p.x, p.y + 0.2, p.z), 5.4, 0x9b5cff, 0.9);
          this.vfx?.slash(new THREE.Vector3(p.x, p.y + 1.4, p.z), e.group.rotation.y, true, 0xb46bff);
          this.callbacks.onBossSlam?.(e);
          m.arms[1].arm.rotation.x = 0.6;
        } else {
          this.vfx?.slash(new THREE.Vector3(p.x, p.y + 0.8, p.z), e.group.rotation.y, false, e.type === 'shade' ? 0xff4d7d : 0x9dff8a);
        }
        this.audio?.enemyAttack();
        e.state = 'recover'; e.stateTime = 0;
        e.cooldown = e.attackCooldown * (0.75 + Math.random() * 0.5);
      }
    } else if (e.state === 'recover') {
      if (e.stateTime > 0.35) {
        e.state = 'chase'; e.stateTime = 0;
        if (e.type === 'moss') m.body.scale.y = 1;
      }
    } else if (e.state === 'roar') {
      if (e.stateTime > 1.2) { e.state = 'chase'; e.stateTime = 0; e.cooldown = 0.8; }
    }

    // boss phase 2
    if (e.type === 'boss' && e.phase === 1 && e.hp < e.maxHp * 0.5) {
      e.phase = 2;
      e.speed *= 1.2;
      e.attackCooldown *= 0.75;
      this.callbacks.onBossPhase?.(e);
      this.audio?.bossRoar();
      this.vfx?.shockwave(new THREE.Vector3(p.x, p.y + 0.3, p.z), 8, 0xd78bff, 1.2);
      this.vfx?.hitSpark(new THREE.Vector3(p.x, p.y + 2.5, p.z), 0xd78bff, 28);
      e.group.scale.setScalar(1.1);
    }

    // health bar follow + visibility
    e.bar.sprite.visible = e.engaged || e.hp < e.maxHp;
    if (e.bar.sprite.visible) {
      e.bar.sprite.position.y = e.height + 0.35;
    }
  }

  _collide(e) {
    const p = e.group.position;
    const cols = e.inDungeon ? this.world.dungeonColliders : this.world.colliders;
    for (const c of cols) {
      const dx = p.x - c.x, dz = p.z - c.z;
      const d = Math.hypot(dx, dz);
      const min = c.r + e.radius * 0.55;
      if (d < min && d > 0.001) {
        p.x = c.x + dx / d * min;
        p.z = c.z + dz / d * min;
      }
    }
    if (e.inDungeon) {
      p.x = clamp(p.x, -14.5, 14.5);
      p.z = clamp(p.z, -246, -199);
    } else {
      const d = Math.hypot(p.x, p.z);
      if (d > 94) { p.x *= 94 / d; p.z *= 94 / d; }
    }
    p.y = e.inDungeon ? 0.3 : this.world.heightAt(p.x, p.z);
  }

  _setFlash(e, on) {
    e._flashed = on;
    e.group.traverse(obj => {
      if (!obj.isMesh || !obj.material) return;
      const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
      for (const mat of mats) {
        if (!mat.emissive) continue;
        if (on) {
          if (!mat.userData._origEmissive) {
            mat.userData._origEmissive = mat.emissive.getHex();
            mat.userData._origIntensity = mat.emissiveIntensity ?? 1;
          }
          mat.emissive.setHex(0xffffff);
          mat.emissiveIntensity = 1.4;
        } else if (mat.userData._origEmissive !== undefined) {
          mat.emissive.setHex(mat.userData._origEmissive);
          mat.emissiveIntensity = mat.userData._origIntensity;
        }
      }
    });
  }

  damage(e, amount, dir, knockback = 2, heavy = false, source = 'sword') {
    if (!e || e.dead || e.invuln > 0) return false;
    e.hp -= amount;
    e.engaged = true;
    e.invuln = 0.06;
    e.flash = 0.13;
    e._flashed = false;
    this._setFlash(e, true);
    e.stun = heavy ? 0.42 : 0.2;
    e.state = 'hurt'; e.stateTime = 0;
    if (e.type !== 'boss') {
      e.kb.set(dir.x, 0, dir.z).normalize().multiplyScalar(knockback);
      e.bar.sprite.visible = true;
    } else {
      e.kb.set(dir.x, 0, dir.z).normalize().multiplyScalar(knockback * 0.08);
    }
    drawHealthBar(e.bar, Math.max(0, e.hp / e.maxHp), e.type === 'boss');
    const hitPos = new THREE.Vector3(e.group.position.x, e.group.position.y + e.height * 0.6, e.group.position.z);
    this.vfx?.hitSpark(hitPos, heavy ? 0xffd37a : 0xbffcff, heavy ? 22 : 13);
    this.vfx?.damageNumber(hitPos, Math.round(amount), heavy ? 'gold' : 'white');
    this.audio?.hit(heavy);
    if (e.type === 'boss') this.callbacks.onBossDamage?.(e, amount);
    if (e.hp <= 0) this._kill(e);
    return true;
  }

  _kill(e) {
    e.dead = true;
    e.hp = 0;
    e.deathTime = 0;
    e.kb.set(0, 0, 0);
    this.vfx?.deathBurst(e.group.position.clone().add(new THREE.Vector3(0, e.height * 0.5, 0)), e.type === 'boss' ? 0xd78bff : e.type === 'shade' ? 0xb46bff : 0x9dff8a);
    this.audio?.enemyDeath(e.type === 'boss');
    if (e.type === 'boss') {
      this.bossActive = false;
      this.bossDefeated = true;
      this.callbacks.onBossDefeated?.(e);
    } else {
      this.callbacks.onEnemyDeath?.(e);
      if (e.spawn) e.spawn.timer = 26 + Math.random() * 8;
    }
  }

  enemiesInArc(origin, yaw, range, arc) {
    const hits = [];
    for (const e of this.enemies) {
      if (e.dead) continue;
      if (e.inDungeon && this.zone !== 'dungeon') continue;
      if (!e.inDungeon && this.zone !== 'island') continue;
      const dx = e.group.position.x - origin.x;
      const dz = e.group.position.z - origin.z;
      const d = Math.hypot(dx, dz);
      if (d > range + e.radius) continue;
      const ang = Math.atan2(dx, dz);
      let diff = Math.abs(ang - yaw);
      while (diff > Math.PI) diff = Math.abs(diff - Math.PI * 2);
      if (diff > arc * 0.5) continue;
      hits.push(e);
    }
    return hits;
  }

  enemiesInRadius(center, radius) {
    return this.enemies.filter(e => {
      if (e.dead) return false;
      if (e.inDungeon && this.zone !== 'dungeon') return false;
      if (!e.inDungeon && this.zone !== 'island') return false;
      return Math.hypot(e.group.position.x - center.x, e.group.position.z - center.z) < radius + e.radius;
    });
  }

  resetBoss() {
    if (!this.boss || this.bossDefeated) return;
    const b = this.boss;
    b.hp = b.maxHp; b.dead = false; b.engaged = false; b.state = 'idle'; b.phase = 1;
    b.group.position.set(0, 0.3, -232); b.group.scale.setScalar(1.05);
    b.group.rotation.set(0, 0, 0);
    b.bar.sprite.visible = false;
    drawHealthBar(b.bar, 1, true);
    this.bossActive = false;
  }

  resetMinions() {
    for (const e of this.enemies) {
      if (e.type === 'boss' || e.dead) continue;
      e.hp = e.maxHp; e.state = 'idle'; e.engaged = false;
      e.group.position.copy(e.home);
      e.group.rotation.set(0, 0, 0);
      e.bar.sprite.visible = false;
      drawHealthBar(e.bar, 1, false);
    }
  }
}

import * as THREE from 'three';

const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function glowTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 1, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.22, 'rgba(210,250,255,.8)');
  g.addColorStop(0.55, 'rgba(125,249,255,.25)');
  g.addColorStop(1, 'rgba(125,249,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(c);
}
const GLOW = glowTexture();
const sparkGeo = new THREE.OctahedronGeometry(0.07, 0);
const ringGeo = new THREE.RingGeometry(0.8, 1, 40);

export class VFXManager {
  constructor(scene) {
    this.scene = scene;
    this.effects = [];
    this.projectiles = [];
    this.time = 0;
  }

  _add(mesh, life, update) {
    this.scene.add(mesh);
    const e = { mesh, life, age: 0, update };
    this.effects.push(e);
    return e;
  }

  update(dt) {
    this.time += dt;
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i];
      e.age += dt;
      const t = e.age / e.life;
      if (t >= 1) {
        this.scene.remove(e.mesh);
        e.mesh.traverse?.(o => {
          if (o.geometry && o.geometry !== ringGeo && o.geometry !== sparkGeo) o.geometry.dispose?.();
          if (o.material) {
            if (o.material.map && o.material.map !== GLOW) o.material.map.dispose?.();
            o.material.dispose?.();
          }
        });
        this.effects.splice(i, 1);
        continue;
      }
      e.update?.(t, e, dt);
    }
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.age += dt;
      p.pos.addScaledVector(p.dir, p.speed * dt);
      p.mesh.position.copy(p.pos);
      p.mesh.rotation.y += dt * 6;
      if (p.light) p.light.position.copy(p.pos);
      // trail
      p.trailTimer -= dt;
      if (p.trailTimer <= 0) {
        p.trailTimer = 0.035;
        this.hitSpark(p.pos.clone(), p.color, 3, 0.3, 0.6);
      }
      const hit = p.hitTest?.(p.pos);
      if (hit || p.age > p.life || p.pos.y < -1) {
        this.explode(p.pos.clone(), p.color, p.onExplode);
        this.scene.remove(p.mesh);
        if (p.light) this.scene.remove(p.light);
        p.mesh.traverse?.(o => { o.material?.dispose?.(); });
        this.projectiles.splice(i, 1);
      }
    }
  }

  slash(pos, yaw, heavy = false, color = 0x7df9ff) {
    const group = new THREE.Group();
    group.position.copy(pos);
    group.rotation.y = yaw;
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: heavy ? 0.95 : 0.8, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const arc = new THREE.Mesh(new THREE.RingGeometry(0.7, 1.75, 26, 1, Math.PI / 2 - 1.0, 2.0), mat);
    arc.rotation.x = Math.PI / 2;
    group.add(arc);
    if (heavy) {
      const arc2 = new THREE.Mesh(new THREE.RingGeometry(1.15, 2.2, 26, 1, Math.PI / 2 - 1.2, 2.4), mat.clone());
      arc2.material.opacity = 0.45; arc2.rotation.x = Math.PI / 2; arc2.rotation.z = 0.1; group.add(arc2);
    }
    this._add(group, heavy ? 0.38 : 0.26, (t, e) => {
      const s = 0.75 + t * (heavy ? 0.9 : 0.65);
      group.scale.set(s, s, s);
      group.rotation.y = yaw + (heavy ? 0 : (t - 0.5) * 0.4);
      group.position.y = pos.y + Math.sin(t * Math.PI) * 0.06;
      group.traverse(o => { if (o.material && o.material.opacity !== undefined) o.material.opacity = (heavy ? 0.95 : 0.8) * (1 - t) ** 1.4; });
    });
  }

  hitSpark(pos, color = 0xffffff, count = 12, size = 1, life = 0.55) {
    const geo = new THREE.BufferGeometry();
    const positions = new Float32Array(count * 3);
    const velocities = [];
    for (let i = 0; i < count; i++) {
      positions[i * 3] = pos.x; positions[i * 3 + 1] = pos.y; positions[i * 3 + 2] = pos.z;
      const a = Math.random() * TAU, e = Math.random() * Math.PI - Math.PI / 2;
      const sp = (1.5 + Math.random() * 4) * size;
      velocities.push(new THREE.Vector3(Math.cos(a) * Math.cos(e) * sp, Math.sin(e) * sp + 1, Math.sin(a) * Math.cos(e) * sp));
    }
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({ color, size: 0.12 * size, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
    const points = new THREE.Points(geo, mat);
    const origin = pos.clone();
    this._add(points, life, (t) => {
      const arr = geo.attributes.position.array;
      for (let i = 0; i < count; i++) {
        const v = velocities[i];
        arr[i * 3] = origin.x + v.x * t * life;
        arr[i * 3 + 1] = origin.y + (v.y - 3.5 * t * life) * t * life;
        arr[i * 3 + 2] = origin.z + v.z * t * life;
      }
      geo.attributes.position.needsUpdate = true;
      mat.opacity = 1 - t;
      mat.size = 0.12 * size * (1 - t * 0.5);
    });
  }

  shockwave(pos, radius = 4, color = 0x7df9ff, life = 0.7) {
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.75, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const ring = new THREE.Mesh(ringGeo, mat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.copy(pos);
    ring.position.y += 0.08;
    this._add(ring, life, (t) => {
      const s = 0.3 + t * radius;
      ring.scale.set(s, s, s);
      mat.opacity = 0.75 * (1 - t) ** 1.5;
    });
    // vertical light column
    const colMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.25, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const col = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 1.2, 3, 12, 1, true), colMat);
    col.position.copy(pos); col.position.y += 1.5;
    this._add(col, life * 0.7, (t) => {
      col.scale.set(1 + t * radius * 0.35, 1, 1 + t * radius * 0.35);
      colMat.opacity = 0.25 * (1 - t);
    });
  }

  telegraph(pos, radius, color = 0xff4668, life = 0.5) {
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.72, 1, 40), mat);
    ring.rotation.x = -Math.PI / 2; ring.position.copy(pos); ring.position.y += 0.04;
    this._add(ring, life, (t) => {
      const s = radius * (0.3 + t * 0.7);
      ring.scale.set(s, s, s);
      mat.opacity = 0.25 + Math.sin(t * Math.PI * 5) * 0.2 + t * 0.15;
    });
    const discMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.12, side: THREE.DoubleSide, depthWrite: false });
    const disc = new THREE.Mesh(new THREE.CircleGeometry(1, 32), discMat);
    disc.rotation.x = -Math.PI / 2; disc.position.copy(pos); disc.position.y += 0.03;
    this._add(disc, life, (t) => { const s = radius * t; disc.scale.set(s, s, s); discMat.opacity = 0.16 * (1 - t); });
  }

  damageNumber(pos, amount, style = 'white') {
    const color = style === 'gold' ? '#ffd37a' : style === 'heal' ? '#9dffcf' : '#e9fbff';
    const c = document.createElement('canvas'); c.width = 160; c.height = 80;
    const ctx = c.getContext('2d');
    ctx.font = 'bold 54px "Trebuchet MS", sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.lineWidth = 7; ctx.strokeStyle = 'rgba(4,8,20,.85)';
    ctx.strokeText(String(amount), 80, 42);
    ctx.fillStyle = color;
    ctx.shadowColor = color; ctx.shadowBlur = 14;
    ctx.fillText(String(amount), 80, 42);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: false });
    const sp = new THREE.Sprite(mat);
    sp.position.copy(pos); sp.position.y += 0.7;
    sp.scale.set(1.2, 0.6, 1); sp.renderOrder = 20;
    const start = sp.position.clone();
    this._add(sp, 0.85, (t) => {
      sp.position.y = start.y + t * 1.1;
      sp.position.x = start.x + Math.sin(t * 8) * 0.08;
      sp.material.opacity = 1 - t * t;
      const s = 1.2 * (0.7 + Math.min(0.5, t * 2));
      sp.scale.set(s, s * 0.5, 1);
    });
  }

  deathBurst(pos, color = 0x9dff8a) {
    this.shockwave(pos, 2.4, color, 0.6);
    this.hitSpark(pos, color, 26, 1.4, 0.9);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false });
    const soul = new THREE.Mesh(new THREE.OctahedronGeometry(0.2, 0), mat);
    soul.position.copy(pos);
    this._add(soul, 0.9, (t) => {
      soul.position.y = pos.y + t * 2.2;
      soul.scale.setScalar(1 + t * 0.8);
      mat.opacity = 0.8 * (1 - t);
    });
  }

  pickupBurst(pos, color = 0xffd37a) {
    this.hitSpark(pos, color, 12, 0.8, 0.6);
  }

  heal(pos) {
    this.shockwave(pos, 2.2, 0x9dffcf, 0.8);
    this.hitSpark(pos.clone().add(new THREE.Vector3(0, 0.8, 0)), 0x9dffcf, 18, 0.9, 0.9);
  }

  levelUp(pos) {
    this.shockwave(pos, 4.5, 0xffd37a, 1.0);
    this.hitSpark(pos.clone().add(new THREE.Vector3(0, 1, 0)), 0xffe7a9, 34, 1.4, 1.2);
    const mat = new THREE.MeshBasicMaterial({ color: 0xffd37a, transparent: true, opacity: 0.8, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const ring = new THREE.Mesh(new THREE.CylinderGeometry(1.0, 1.0, 0.1, 32, 1, true), mat);
    ring.position.copy(pos); ring.position.y += 0.4;
    this._add(ring, 1.0, (t) => {
      ring.position.y = pos.y + 0.3 + t * 2.4;
      ring.scale.set(1 + t * 0.8, 1, 1 + t * 0.8);
      mat.opacity = 0.8 * (1 - t);
    });
  }

  magicBolt(origin, dir, hitTest, onExplode, color = 0x7df9ff) {
    const group = new THREE.Group();
    const core = new THREE.Mesh(new THREE.IcosahedronGeometry(0.22, 1), new THREE.MeshBasicMaterial({ color: 0xffffff }));
    group.add(core);
    const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: GLOW, color, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }));
    halo.scale.set(1.8, 1.8, 1); group.add(halo);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.38, 0.035, 6, 18), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false }));
    ring.rotation.x = Math.PI / 2; group.add(ring);
    const light = new THREE.PointLight(color, 18, 12, 2);
    group.position.copy(origin); light.position.copy(origin);
    this.scene.add(group); this.scene.add(light);
    this.projectiles.push({
      mesh: group, light, pos: origin.clone(), dir: dir.clone().normalize(),
      speed: 23, age: 0, life: 1.6, trailTimer: 0, color, hitTest, onExplode,
    });
  }

  explode(pos, color = 0x7df9ff, onExplode) {
    this.shockwave(pos, 5.0, color, 0.8);
    this.hitSpark(pos, color, 34, 1.6, 0.9);
    const light = new THREE.PointLight(color, 35, 16, 2);
    light.position.copy(pos); this.scene.add(light);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
    const sphere = new THREE.Mesh(new THREE.IcosahedronGeometry(0.5, 1), mat);
    sphere.position.copy(pos);
    this._add(sphere, 0.5, (t) => {
      sphere.scale.setScalar(1 + t * 9);
      mat.opacity = 1 - t;
      light.intensity = 35 * (1 - t);
      if (t > 0.9) this.scene.remove(light);
    });
    onExplode?.(pos);
  }

  swordTrail(pos, yaw, color = 0x7df9ff) {
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.5, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const arc = new THREE.Mesh(new THREE.RingGeometry(0.9, 1.45, 18, 1, Math.PI / 2 - 0.65, 1.3), mat);
    arc.rotation.x = Math.PI / 2; arc.rotation.y = yaw;
    arc.position.copy(pos); arc.position.y += 1.05;
    this._add(arc, 0.18, (t) => { mat.opacity = 0.5 * (1 - t); arc.scale.setScalar(1 + t * 0.4); });
  }
}

/* Tiny procedural soundtrack + SFX engine (WebAudio, no assets). */
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.noiseBuffer = null;
    this.muted = false;
    this.mood = 'island';
    this.nextChord = 0;
    this.nextArp = 0;
    this.nextBass = 0;
    this.chordIndex = 0;
    this.arpIndex = 0;
    this.ready = false;
    this.timer = 0;
    this.combatHeat = 0;
  }

  init() {
    if (this.ready) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.7;
    this.master.connect(this.ctx.destination);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.16;
    const lp = this.ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.frequency.value = 5200;
    this.musicGain.connect(lp); lp.connect(this.master);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.32;
    this.sfxGain.connect(this.master);

    // gentle delay for the bells
    this.delay = this.ctx.createDelay(1.2);
    this.delay.delayTime.value = 0.34;
    this.delayFeedback = this.ctx.createGain();
    this.delayFeedback.gain.value = 0.28;
    this.delayWet = this.ctx.createGain();
    this.delayWet.gain.value = 0.3;
    this.delay.connect(this.delayFeedback); this.delayFeedback.connect(this.delay);
    this.delay.connect(this.delayWet); this.delayWet.connect(this.musicGain);

    const len = this.ctx.sampleRate * 1.2;
    this.noiseBuffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = this.noiseBuffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;

    this.nextChord = this.ctx.currentTime + 0.2;
    this.nextArp = this.ctx.currentTime + 1.2;
    this.nextBass = this.ctx.currentTime + 0.2;
    this.ready = true;
  }

  resume() {
    if (!this.ctx) this.init();
    if (this.ctx?.state === 'suspended') this.ctx.resume();
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.7, this.ctx.currentTime, 0.05);
  }

  setMood(mood) {
    if (this.mood === mood) return;
    this.mood = mood;
    this.chordIndex = 0;
    this.nextChord = this.ctx ? this.ctx.currentTime + 0.1 : 0;
    this.nextArp = this.ctx ? this.ctx.currentTime + 0.8 : 0;
  }

  _note(freq, dur, type = 'sine', gain = 0.1, when = 0, dest = null, attack = 0.03, release = 0.3, detune = 0) {
    if (!this.ready) return;
    const t = when || this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type; osc.frequency.value = freq; osc.detune.value = detune;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + Math.max(attack + 0.05, dur));
    osc.connect(g); g.connect(dest || this.musicGain);
    osc.start(t); osc.stop(t + dur + 0.08);
    return g;
  }

  _noise(dur, gain = 0.2, when = 0, filterFreq = 1800, q = 1, type = 'bandpass') {
    if (!this.ready) return;
    const t = when || this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type; f.frequency.value = filterFreq; f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f); f.connect(g); g.connect(this.sfxGain);
    src.start(t); src.stop(t + dur + 0.02);
  }

  update(dt) {
    if (!this.ready) return;
    this.timer += dt;
    const now = this.ctx.currentTime;
    const boss = this.mood === 'boss';
    const dungeon = this.mood === 'dungeon';
    // chords
    if (now >= this.nextChord) {
      const island = [
        [146.83, 220.0, 293.66, 369.99],
        [130.81, 196.0, 261.63, 329.63],
        [174.61, 261.63, 349.23, 440.0],
        [164.81, 246.94, 329.63, 415.3],
      ];
      const dark = [
        [110.0, 164.81, 220.0, 261.63],
        [98.0, 146.83, 196.0, 233.08],
        [87.31, 130.81, 174.61, 220.0],
        [103.83, 155.56, 207.65, 246.94],
      ];
      const prog = boss || dungeon ? dark : island;
      const chord = prog[this.chordIndex % prog.length];
      this.chordIndex++;
      const dur = boss ? 3.2 : 4.4;
      chord.forEach((f, i) => {
        this._note(f, dur, i === 0 ? 'triangle' : 'sine', i === 0 ? 0.055 : 0.035, now, null, 0.8, dur * 0.8, i % 2 ? 3 : -3);
      });
      // airy pad high
      this._note(chord[2] * 2, dur * 0.9, 'sine', 0.018, now + 0.2, null, 1.2, dur);
      this.nextChord = now + dur;
    }
    // arpeggio bells
    if (now >= this.nextArp) {
      const scale = boss ? [220, 261.63, 311.13, 369.99, 440, 523.25] : [293.66, 369.99, 440, 523.25, 587.33, 739.99, 880];
      const f = scale[(this.arpIndex * 3 + this.chordIndex) % scale.length];
      const g = this._note(f, boss ? 0.5 : 0.9, 'sine', boss ? 0.035 : 0.045, now, null, 0.005, boss ? 0.4 : 0.8);
      if (g) { g.connect(this.delay); }
      this.arpIndex++;
      this.nextArp = now + (boss ? 0.46 : dungeon ? 1.1 : 0.72);
    }
    // bass pulse
    if (now >= this.nextBass) {
      const root = boss ? 55 : dungeon ? 73.42 : 73.42;
      this._note(root, boss ? 0.55 : 1.6, boss ? 'sawtooth' : 'triangle', boss ? 0.03 : 0.045, now, null, 0.02, boss ? 0.5 : 1.4);
      this.nextBass = now + (boss ? 0.75 : 2.8);
    }
    // distant wind / cave rumble
    if (this.timer > 7) {
      this.timer = 0;
      this._noise(dungeon || boss ? 3.2 : 4.5, 0.012, now, dungeon ? 260 : 900, 0.6, 'lowpass');
    }
  }

  /* ---------------- SFX ---------------- */
  swing(heavy = false) {
    if (!this.ready) return;
    this._noise(heavy ? 0.32 : 0.18, heavy ? 0.25 : 0.16, 0, heavy ? 700 : 1400, 1.4);
    const f = heavy ? 180 : 320;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator(); const g = this.ctx.createGain();
    osc.type = 'triangle'; osc.frequency.setValueAtTime(f, t); osc.frequency.exponentialRampToValueAtTime(f * 0.5, t + 0.2);
    g.gain.setValueAtTime(0.08, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.22);
    osc.connect(g); g.connect(this.sfxGain); osc.start(t); osc.stop(t + 0.25);
  }

  hit(heavy = false) {
    if (!this.ready) return;
    this._noise(heavy ? 0.16 : 0.09, heavy ? 0.3 : 0.2, 0, heavy ? 500 : 1100, 0.9);
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator(); const g = this.ctx.createGain();
    osc.type = 'sine'; osc.frequency.setValueAtTime(heavy ? 120 : 200, t); osc.frequency.exponentialRampToValueAtTime(55, t + 0.16);
    g.gain.setValueAtTime(heavy ? 0.24 : 0.15, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
    osc.connect(g); g.connect(this.sfxGain); osc.start(t); osc.stop(t + 0.2);
  }

  enemyWindup() { this._noise(0.14, 0.06, 0, 420, 2.5); }
  enemyAttack() { this._noise(0.14, 0.12, 0, 900, 1.2); }
  enemyDeath(boss = false) {
    this._noise(boss ? 1.4 : 0.4, boss ? 0.3 : 0.14, 0, boss ? 200 : 600, 0.7, 'lowpass');
    const t = this.ctx?.currentTime;
    if (!t) return;
    const osc = this.ctx.createOscillator(); const g = this.ctx.createGain();
    osc.type = 'sine'; osc.frequency.setValueAtTime(boss ? 90 : 260, t); osc.frequency.exponentialRampToValueAtTime(boss ? 35 : 90, t + (boss ? 1.2 : 0.3));
    g.gain.setValueAtTime(0.18, t); g.gain.exponentialRampToValueAtTime(0.001, t + (boss ? 1.3 : 0.35));
    osc.connect(g); g.connect(this.sfxGain); osc.start(t); osc.stop(t + (boss ? 1.4 : 0.4));
  }

  magic() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    for (let i = 0; i < 3; i++) {
      const osc = this.ctx.createOscillator(); const g = this.ctx.createGain();
      osc.type = 'sine'; osc.frequency.setValueAtTime(240 + i * 80, t);
      osc.frequency.exponentialRampToValueAtTime(960 + i * 240, t + 0.5);
      g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.07, t + 0.08); g.gain.exponentialRampToValueAtTime(0.001, t + 0.7);
      osc.connect(g); g.connect(this.sfxGain); osc.start(t); osc.stop(t + 0.75);
    }
    this._noise(0.5, 0.12, 0, 2600, 0.8);
  }

  pickup() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    [880, 1174.66, 1567.98].forEach((f, i) => {
      this._note(f, 0.35, 'sine', 0.09, t + i * 0.06, this.sfxGain, 0.005, 0.3);
    });
  }

  coin() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    this._note(1318.5, 0.12, 'triangle', 0.05, t, this.sfxGain, 0.005, 0.1);
    this._note(1760, 0.18, 'triangle', 0.04, t + 0.05, this.sfxGain, 0.005, 0.14);
  }

  chest() {
    if (!this.ready) return;
    this._noise(0.3, 0.16, 0, 500, 0.8);
    const t = this.ctx.currentTime;
    [392, 523.25, 659.25, 783.99].forEach((f, i) => this._note(f, 0.5, 'sine', 0.08, t + 0.08 + i * 0.08, this.sfxGain, 0.01, 0.4));
  }

  quest() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => this._note(f, 0.7, 'triangle', 0.1, t + i * 0.12, this.sfxGain, 0.01, 0.55));
  }

  levelUp() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    [392, 523.25, 659.25, 783.99, 1046.5].forEach((f, i) => {
      this._note(f, 0.9, 'sine', 0.1, t + i * 0.09, this.sfxGain, 0.01, 0.8);
      this._note(f * 2, 0.6, 'sine', 0.03, t + i * 0.09, this.sfxGain, 0.01, 0.5);
    });
  }

  jump() { this._noise(0.16, 0.08, 0, 1200, 1.5); }
  dodge() { this._noise(0.24, 0.12, 0, 700, 1.2); }
  hurt() {
    if (!this.ready) return;
    this._noise(0.24, 0.22, 0, 500, 0.7, 'lowpass');
    this._note(120, 0.3, 'sawtooth', 0.08, 0, this.sfxGain, 0.005, 0.25);
  }

  heal() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    [523.25, 659.25, 880].forEach((f, i) => this._note(f, 0.6, 'sine', 0.07, t + i * 0.1, this.sfxGain, 0.02, 0.5));
  }

  checkpoint() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    [440, 554.37, 659.25, 880].forEach((f, i) => this._note(f, 1.1, 'sine', 0.08, t + i * 0.14, this.sfxGain, 0.02, 0.9));
  }

  click() {
    if (!this.ready) return;
    this._note(620, 0.09, 'triangle', 0.06, 0, this.sfxGain, 0.003, 0.07);
  }

  bossRoar() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    this._noise(1.6, 0.4, t, 180, 0.8, 'lowpass');
    [55, 73.42, 110].forEach((f, i) => {
      const osc = this.ctx.createOscillator(); const g = this.ctx.createGain();
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(f, t); osc.frequency.exponentialRampToValueAtTime(f * 0.7, t + 1.4);
      g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.09, t + 0.2); g.gain.exponentialRampToValueAtTime(0.001, t + 1.5);
      osc.connect(g); g.connect(this.sfxGain); osc.start(t); osc.stop(t + 1.6);
    });
  }

  bossGrowl() {
    if (!this.ready) return;
    this._noise(0.5, 0.16, 0, 220, 1.0, 'lowpass');
    this._note(82, 0.45, 'sawtooth', 0.06, 0, this.sfxGain, 0.02, 0.4);
  }

  victory() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    [392, 523.25, 659.25, 783.99, 1046.5, 1318.5].forEach((f, i) => {
      this._note(f, 1.8, 'triangle', 0.1, t + i * 0.16, this.sfxGain, 0.02, 1.5);
      this._note(f * 0.5, 1.8, 'sine', 0.05, t + i * 0.16, this.sfxGain, 0.05, 1.4);
    });
  }
}

