1126:   for (const c of cols) {
1127:     if (c.r < 1.0) continue;
1128:     const fx = target.x - c.x;
1129:     const fz = target.z - c.z;
1130:     const rr = c.r + 0.42;
1131:     const a = len2;
1132:     const b = 2 * (fx * dx + fz * dz);
1133:     const cc = fx * fx + fz * fz - rr * rr;
1134:     const disc = b * b - 4 * a * cc;
