1142:     desired.z = target.z + dz * t;
1143:     desired.y = target.y + (desired.y - target.y) * t;
1144:     if (game.zone === 'island') {
1145:       const gh = world.heightAt(desired.x, desired.z);
1146:       if (desired.y < gh + 0.55) desired.y = gh + 0.55;
1147:     } else {
1148:       desired.y = Math.max(desired.y, 1.0);
1149:     }
1150:   }
1151: }
