91:     const panel = mesh(new THREE.PlaneGeometry(0.25, 0.42), toon(i % 2 ? HERO_COLORS.outfitLight : HERO_COLORS.outfit, { side: THREE.DoubleSide }));
92:     panel.position.set(Math.cos(a) * 0.2, -0.12, Math.sin(a) * 0.2);
93:     panel.rotation.y = -a + Math.PI / 2;
94:     panel.rotation.x = 0.08;
95:     hips.add(panel);
96:   }
97: 
98:   /* --- head --- */
99:   const head = new THREE.Group();
100:   head.position.y = 0.72; torso.add(head);
101:   const skull = mesh(new THREE.SphereGeometry(0.235, 12, 10), skin);
102:   skull.scale.set(0.96, 1.04, 0.96); head.add(skull);
103:   const jaw = mesh(new THREE.SphereGeometry(0.16, 10, 8), skin);
104:   jaw.scale.set(0.82, 0.7, 0.9); jaw.position.set(0, -0.11, 0.06); head.add(jaw);
105:   const neck = mesh(new THREE.CylinderGeometry(0.09, 0.1, 0.18, 6), skin);
106:   neck.position.y = -0.24; head.add(neck);
107:   // hair mass
108:   const hairBack = mesh(new THREE.SphereGeometry(0.26, 10, 8), hair);
109:   hairBack.scale.set(1.02, 1.02, 1.04); hairBack.position.set(0, 0.02, -0.035); head.add(hairBack);
110:   const fringe = mesh(new THREE.SphereGeometry(0.245, 10, 8, 0, Math.PI * 2, 0, Math.PI * 0.52), hair);
111:   fringe.scale.set(1.04, 1.0, 1.06); fringe.position.set(0, 0.04, 0.03); head.add(fringe);
112:   // bangs
113:   for (const [x, rot, len] of [[-0.13, 0.3, 0.22], [-0.04, 0.05, 0.25], [0.07, -0.12, 0.22], [0.16, -0.3, 0.18]]) {
114:     const bang = mesh(new THREE.ConeGeometry(0.055, len, 4), hairShade);
115:     bang.position.set(x, 0.13, 0.22); bang.rotation.z = rot; bang.rotation.x = 0.12; head.add(bang);
116:   }
117:   // side locks
118:   for (const sx of [-1, 1]) {
119:     const lock = mesh(new THREE.CapsuleGeometry(0.045, 0.34, 3, 6), hair);
120:     lock.position.set(sx * 0.21, -0.12, 0.03); lock.rotation.z = sx * 0.08; head.add(lock);
121:   }
122:   // long back hair
123:   const backHair = mesh(new THREE.ConeGeometry(0.22, 0.7, 6), hair);
124:   backHair.position.set(0, -0.23, -0.13); backHair.rotation.x = -0.1; head.add(backHair);
125:   // eyes
126:   for (const sx of [-1, 1]) {
127:     const eye = mesh(new THREE.SphereGeometry(0.045, 8, 6), basic(0x15203b), false);
128:     eye.scale.set(0.8, 1.25, 0.35); eye.position.set(sx * 0.085, -0.015, 0.222); head.add(eye);
129:     const iris = mesh(new THREE.SphereGeometry(0.026, 8, 6), basic(0x7df9ff), false);
130:     iris.scale.set(0.9, 1.15, 0.3); iris.position.set(sx * 0.085, -0.012, 0.242); head.add(iris);
131:     const brow = mesh(new THREE.BoxGeometry(0.07, 0.014, 0.02), toon(0x8fb9d0), false);
132:     brow.position.set(sx * 0.085, 0.055, 0.226); brow.rotation.z = sx * -0.1; head.add(brow);
133:   }
134:   const mouth = mesh(new THREE.BoxGeometry(0.045, 0.008, 0.01), toon(0xc97d84), false);
135:   mouth.position.set(0, -0.09, 0.215); head.add(mouth);
136:   // headband / circlet
137:   const circlet = mesh(new THREE.TorusGeometry(0.225, 0.018, 5, 18), gold);
138:   circlet.rotation.x = Math.PI / 2; circlet.position.y = 0.1; head.add(circlet);
139:   const gem = mesh(new THREE.OctahedronGeometry(0.04, 0), basic(0x7df9ff));
140:   gem.position.set(0, 0.11, 0.24); head.add(gem);
141: 
142:   // scarf
143:   const scarf = mesh(new THREE.TorusGeometry(0.14, 0.05, 6, 12), scarfMat);
144:   scarf.rotation.x = Math.PI / 2; scarf.position.set(0, -0.23, 0); torso.add(scarf);
145:   const scarfTails = [];
146:   for (let i = 0; i < 3; i++) {
147:     const tail = mesh(new THREE.PlaneGeometry(0.2 - i * 0.035, 0.78 - i * 0.12), scarfMat, false);
