149:     tail.rotation.x = 0.28; tail.rotation.z = 0.16 - i * 0.16;
150:     torso.add(tail); scarfTails.push(tail);
151:   }
152: 
153:   // split coat tails / short cape, with a bright lining
154:   const cape = new THREE.Group();
155:   cape.position.set(0, 0.42, -0.22);
156:   const capeMat = toon(0x18234a, { side: THREE.DoubleSide });
157:   for (const sx of [-1, 1]) {
158:     const panel = mesh(new THREE.PlaneGeometry(0.27, 0.88), capeMat, false);
159:     panel.position.set(sx * 0.14, -0.42, 0);
160:     panel.rotation.y = sx * 0.22;
161:     cape.add(panel);
162:     const lining = mesh(new THREE.PlaneGeometry(0.2, 0.76), toon(0x7df9ff, { side: THREE.DoubleSide, emissive: 0x1a6b7a, emissiveIntensity: 0.25 }), false);
163:     lining.position.set(sx * 0.145, -0.43, 0.012);
164:     lining.rotation.y = sx * 0.22;
