172:   for (let i = 0; i < 3; i++) {
173:     const seg = mesh(new THREE.ConeGeometry(0.13 - i * 0.025, 0.38, 5), i === 2 ? hairShade : hair, false);
174:     seg.position.set(0, -0.16 - i * 0.26, -0.06 - i * 0.035);
175:     seg.rotation.x = -0.18 - i * 0.06;
