177:   }
178:   const ribbon = mesh(new THREE.BoxGeometry(0.22, 0.08, 0.06), scarfMat, false);
179:   ribbon.position.set(0, -0.02, -0.04); ponytail.add(ribbon);
180:   head.add(ponytail);
181: 
182:   /* --- arms --- */
183:   function makeArm(sx) {
184:     const shoulder = new THREE.Group();
185:     shoulder.position.set(sx * 0.33, 0.44, 0);
