Index: src/style.css
===================================================================
--- src/style.css
+++ src/style.css
@@ -123,9 +123,9 @@
 .quest-obj{font-size:9px;color:#a9c1d8;margin-top:3px;line-height:1.4}
 .quest-item.done .quest-obj{color:#ffd37a}
 .quest-progress{height:2px;background:rgba(255,255,255,.1);margin-top:5px;overflow:hidden}
 .quest-progress i{display:block;height:100%;background:linear-gradient(90deg,var(--cyan),var(--gold));width:0;transition:width .3s}
-.boss-panel{position:absolute;top:74px;left:50%;transform:translateX(-50%);width:min(540px,72vw);text-align:center;animation:bossIn .6s ease both}
+.boss-panel{position:absolute;top:96px;left:50%;transform:translateX(-50%);width:min(540px,72vw);text-align:center;animation:bossIn .6s ease both}
 @keyframes bossIn{from{opacity:0;transform:translate(-50%,-12px)}to{opacity:1;transform:translate(-50%,0)}}
 .boss-top{display:flex;align-items:center;justify-content:center;gap:10px;font-family:var(--display);font-size:13px;letter-spacing:.28em;color:#f4d9ff;text-shadow:0 0 16px rgba(210,120,255,.6)}
 .boss-icon{color:#d78bff}
 .boss-phase{font-family:var(--sans);font-size:8px;letter-spacing:.1em;border:1px solid rgba(215,139,255,.5);padding:1px 5px;color:#e4b5ff}

content.text:
184:.modal{position:fixed;inset:0;z-index:60;display:flex;align-items:center;justify-content:center;padding:22px;background:rgba(3,6,16,.62);backdrop-filter:blur(8px);animation:modalIn .3s ease both}
186:.modal-card{position:relative;width:min(440px,92vw);max-height:90vh;overflow:auto;padding:34px 34px 28px;text-align:center;background:linear-gradient(160deg,rgba(14,25,52,.98),rgba(6,11,26,.98));border:1px solid rgba(174,228,255,.28);border-top:2px solid rgba(125,249,255,.6);box-shadow:var(--shadow),0 0 60px rgba(70,224,255,.1);clip-path:polygon(18px 0,100% 0,100% calc(100% - 18px),calc(100% - 18px) 100%,0 100%,0 18px);animation:cardIn .35s cubic-bezier(.2,.8,.2,1) both}
188:.modal-card h3{font-family:var(--display);font-size:32px;letter-spacing:.14em;margin:8px 0 4px;font-weight:400;color:#f0fbff;text-shadow:0 0 22px rgba(125,249,255,.3)}
189:.modal-card .btn{display:flex;width:100%;margin-top:9px}
190:.pause-mark,.go-mark,.victory-mark{font-size:30px;color:var(--cyan);text-shadow:0 0 24px var(--cyan)}
205:#victory{background:radial-gradient(ellipse at 50% 40%,rgba(24,34,70,.8),rgba(3,6,16,.92))}
206:.victory-rays{position:absolute;inset:-20%;background:conic-gradient(from 0deg,transparent 0deg,rgba(125,249,255,.08) 10deg,transparent 20deg,rgba(255,211,122,.08) 30deg,transparent 40deg);animation:spin 26s linear infinite;pointer-events:none}
207:.victory-card{width:min(560px,94vw);border-top-color:rgba(255,211,122,.7);z-index:1}
208:.victory-card h3{font-size:clamp(26px,5vw,40px);line-height:1.2;color:#fff;text-shadow:0 0 30px rgba(255,211,122,.4)}
209:.victory-card h3 em{font-style:normal;color:#ffd37a;letter-spacing:.24em;font-size:.6em;display:inline-block;margin-top:8px}
210:.victory-copy{font-family:var(--display);font-style:italic;font-size:12px;line-height:1.7;color:#c9dcee;margin:16px 0}
211:.victory-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:rgba(255,211,122,.18);border:1px solid rgba(255,211,122,.2);margin:18px 0 20px}
212:.victory-stats div{background:rgba(9,17,38,.94);padding:10px 4px;display:flex;flex-direction:column;gap:3px}
213:.victory-stats span{font-size:7px;letter-spacing:.14em;text-transform:uppercase;color:#b8a77f}
214:.victory-stats b{font-size:15px;color:#ffe9b7}
243:  .victory-stats{grid-template-columns:repeat(2,1fr)}
.mbtn-heavy{right:76px;bottom:0;border-color:rgba(255,154,213,.5)}
.mbtn-jump{right:0;bottom:0}
.mbtn-dodge{right:76px;bottom:72px;width:46px;height:46px;font-size:15px}
.mbtn-magic{right:14px;bottom:134px;width:46px;height:46px;font-size:17px;border-color:rgba(125,249,255,.55)}
.mbtn-interact{right:78px;bottom:128px;width:44px;height:44px;font-size:13px;border-color:rgba(157,255,207,.5);color:#c9ffe6}
.mobile-sprint{display:none;position:absolute;left:174px;bottom:52px;padding:6px 10px;font-size:8px;letter-spacing:.18em;border:1px solid rgba(174,228,255,.3);color:#b9d7ee;background:rgba(8,16,34,.55);pointer-events:auto;border-radius:2px}
.mobile-sprint.on{background:rgba(125,249,255,.85);color:#04111f;border-color:#dffcff}

/* ---------- dialogue ---------- */
#dialogue{position:fixed;inset:0;z-index:50;display:flex;align-items:flex-end;justify-content:center;padding:0 24px 6vh;background:linear-gradient(180deg,transparent 55%,rgba(3,6,16,.55));pointer-events:none}
.dialogue-box{width:min(780px,94vw);display:flex;gap:18px;padding:20px;background:linear-gradient(150deg,rgba(11,20,44,.96),rgba(7,12,28,.94));border:1px solid rgba(174,228,255,.32);border-top:2px solid rgba(125,249,255,.65);box-shadow:0 24px 70px rgba(0,0,0,.6),0 0 40px rgba(70,224,255,.1);clip-path:polygon(14px 0,100% 0,100% calc(100% - 14px),calc(100% - 14px) 100%,0 100%,0 14px);pointer-events:auto;animation:dlgIn .35s ease both}
@keyframes dlgIn{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
.dialogue-portrait{flex:0 0 76px;height:76px;border:1px solid rgba(174,228,255,.35);background:radial-gradient(circle at 50% 30%,rgba(125,249,255,.25),transparent 65%),linear-gradient(150deg,#27406b,#10172e);display:flex;align-items:center;justify-content:center;font-family:var(--display);font-size:38px;color:#e2fbff;text-shadow:0 0 18px var(--cyan);clip-path:polygon(0 0,100% 0,100% 78%,78% 100%,0 100%)}
.dialogue-main{flex:1;min-width:0}
.dialogue-name{font-family:var(--display);font-size:16px;letter-spacing:.16em;color:#ffd37a;margin-bottom:5px}
.dialogue-text{font-size:13px;line-height:1.65;color:#d9eaf8;min-height:42px}
.dialogue-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:12px}
.dialogue-actions button{padding:8px 16px;font-size:10px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;border:1px solid rgba(174,228,255,.28);background:rgba(18,34,66,.8);color:#dff4ff;transition:background .15s}
.dialogue-actions button:hover{background:rgba(45,86,132,.9);border-color:rgba(125,249,255,.6)}
.dialogue-actions button.primary{background:linear-gradient(120deg,#7df9ff,#c8fbff);color:#06142a;border-color:#fff}
.dialogue-actions button.gold{background:linear-gradient(120deg,#ffd37a,#ffeec2);color:#241603;border-color:#fff2c9}
.dialogue-actions button:disabled{opacity:.4;cursor:not-allowed}

/* ---------- modals ---------- */
.modal{position:fixed;inset:0;z-index:60;display:flex;align-items:center;justify-content:center;padding:22px;background:rgba(3,6,16,.62);backdrop-filter:blur(8px);animation:modalIn .3s ease both}
@keyframes modalIn{from{opacity:0}to{opacity:1}}
.modal-card{position:relative;width:min(440px,92vw);max-height:90vh;overflow:auto;padding:34px 34px 28px;text-align:center;background:linear-gradient(160deg,rgba(14,25,52,.98),rgba(6,11,26,.98));border:1px solid rgba(174,228,255,.28);border-top:2px solid rgba(125,249,255,.6);box-shadow:var(--shadow),0 0 60px rgba(70,224,255,.1);clip-path:polygon(18px 0,100% 0,100% calc(100% - 18px),calc(100% - 18px) 100%,0 100%,0 18px);animation:cardIn .35s cubic-bezier(.2,.8,.2,1) both}
@keyframes cardIn{from{opacity:0;transform:translateY(14px) scale(.98)}to{opacity:1;transform:none}}
.modal-card h3{font-family:var(--display);font-size:32px;letter-spacing:.14em;margin:8px 0 4px;font-weight:400;color:#f0fbff;text-shadow:0 0 22px rgba(125,249,255,.3)}
.modal-card .btn{display:flex;width:100%;margin-top:9px}
.pause-mark,.go-mark,.victory-mark{font-size:30px;color:var(--cyan);text-shadow:0 0 24px var(--cyan)}
.go-mark{color:#b58cff;text-shadow:0 0 24px #8b5cf6}
.pause-sub{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:#9db4cd;margin:0 0 20px}
.pause-stats{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:rgba(174,228,255,.1);border:1px solid rgba(174,228,255,.12);margin-bottom:18px}
.pause-stats div{background:rgba(9,17,38,.9);padding:10px;display:flex;flex-direction:column;gap:3px}
.pause-stats span{font-size:8px;letter-spacing:.18em;text-transform:uppercase;color:#8ea7c0}
.pause-stats b{font-size:16px;color:#eaf9ff;font-weight:600}
.controls-card{width:min(600px,94vw)}
.control-grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:rgba(174,228,255,.1);border:1px solid rgba(174,228,255,.12);margin:18px 0;text-align:left}
.control-grid div{background:rgba(9,17,38,.92);padding:9px 12px;display:flex;flex-direction:column;gap:2px}
.control-grid b{font-size:10px;letter-spacing:.1em;color:#ffd37a}
.control-grid span{font-size:9px;color:#a9c1d8}
.controls-note{font-size:9px;line-height:1.6;color:#91a9c2;text-align:left;margin:0 0 16px}
.gameover-card{border-top-color:rgba(181,140,255,.65)}
.gameover-card h3{color:#e8d8ff;text-shadow:0 0 24px rgba(181,140,255,.4)}
#victory{background:radial-gradient(ellipse at 50% 40%,rgba(24,34,70,.8),rgba(3,6,16,.92))}
.victory-rays{position:absolute;inset:-20%;background:conic-gradient(from 0deg,transparent 0deg,rgba(125,249,255,.08) 10deg,transparent 20deg,rgba(255,211,122,.08) 30deg,transparent 40deg);animation:spin 26s linear infinite;pointer-events:none}
.victory-card{width:min(560px,94vw);border-top-color:rgba(255,211,122,.7);z-index:1}
.victory-card h3{font-size:clamp(26px,5vw,40px);line-height:1.2;color:#fff;text-shadow:0 0 30px rgba(255,211,122,.4)}
.victory-card h3 em{font-style:normal;color:#ffd37a;letter-spacing:.24em;font-size:.6em;display:inline-block;margin-top:8px}
.victory-copy{font-family:var(--display);font-style:italic;font-size:12px;line-height:1.7;color:#c9dcee;margin:16px 0}
.victory-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:rgba(255,211,122,.18);border:1px solid rgba(255,211,122,.2);margin:18px 0 20px}
.victory-stats div{background:rgba(9,17,38,.94);padding:10px 4px;display:flex;flex-direction:column;gap:3px}
.victory-stats span{font-size:7px;letter-spacing:.14em;text-transform:uppercase;color:#b8a77f}
.victory-stats b{font-size:15px;color:#ffe9b7}
#fade{position:fixed;inset:0;z-index:80;background:#04060e;opacity:0;pointer-events:none;transition:opacity .45s ease}
#fade.on{opacity:1;pointer-events:all}

/* ---------- responsive ---------- */
@media (max-width:820px){
  #hud{padding:14px}
  .stat-stack{width:min(250px,52vw)}
  .portrait{width:50px;height:50px}
  .portrait-art{font-size:28px}
  .hero-name{font-size:14px}
  .hero-title{display:none}
  .bar.hp{height:14px}.bar.mana{height:9px}.bar.xp{height:6px}
  .bar-label{font-size:8px;padding:0 6px}
  .hud-top-right{top:12px;right:12px}
  .minimap-wrap{width:104px;height:104px}
  .minimap-label{font-size:6px;bottom:4px}
  .currency{padding:4px 8px;font-size:10px;gap:4px}
  .quest-tracker{left:12px;top:98px;width:210px}
  .compass{top:12px;min-width:0;padding:5px 12px;transform:translateX(-50%) scale(.92)}
  .boss-panel{top:96px;width:80vw}
  .interact-prompt{bottom:178px}
  .hud-hint{display:none}
